"""Trust rule: package-manager lockfiles are tool-generated, not hand-edited."""

from __future__ import annotations

from pathlib import PurePosixPath

from ..diff import DiffFile, DiffHunk
from .labels import Trust

# Package-manager lockfiles: regenerated by tooling, not hand-edited.
LOCKFILE_NAMES = frozenset(
    {
        "package-lock.json",
        "yarn.lock",
        "pnpm-lock.yaml",
        "Cargo.lock",
        "Gemfile.lock",
        "poetry.lock",
        # go.sum is the tool-generated checksum lock; go.mod is the editable
        # manifest (dependencies, replace directives, module path) — reviewer-
        # relevant, so it is deliberately NOT trusted.
        "go.sum",
        "composer.lock",
        "Pipfile.lock",
        "bun.lockb",
        "bun.lock",
        "flake.lock",
        "packages.lock.json",
        "paket.lock",
        "pdm.lock",
        "uv.lock",
    }
)


def _lockfile(file: DiffFile, hunk: DiffHunk) -> Trust | None:
    if PurePosixPath(file.new_path).name not in LOCKFILE_NAMES:
        return None
    # A genuine lockfile is added or regenerated in place, never renamed from a
    # non-lockfile. Renaming e.g. `secrets.py` -> `poetry.lock` would otherwise
    # hide the whole file's hand-written content as "generated"; decline a move
    # unless the source was itself a lockfile.
    if file.is_move() and PurePosixPath(file.old_path).name not in LOCKFILE_NAMES:
        return None
    return Trust.LOCKFILE
